INSERT INTO treatments (nombre, descripcion) VALUES
('Azufre mojable', 'Fungicida de contacto preventivo contra oídio. Aplicar cada 10-14 días desde brotación hasta envero. Dosis: 3-4 kg/ha.'),
('Cobre (Caldo Bordelés)', 'Fungicida preventivo contra mildiu y black rot. Mezcla de sulfato de cobre y cal. Aplicar antes de lluvias. Dosis: 2-3 kg/ha.'),
('Mancozeb', 'Fungicida multisitio de amplio espectro. Preventivo contra mildiu, botrytis y black rot. No sistémico. Dosis: 2-2.5 kg/ha.'),
('Fosetil-Al', 'Fungicida sistémico contra oomicetos (mildiu). Acción curativa y preventiva. Penetra en tejidos. Dosis: 2-3 kg/ha.'),
('Tebuconazol', 'Fungicida sistémico triazol contra oídio y botrytis. Acción curativa. Respetar plazo de seguridad. Dosis: 0.3-0.5 L/ha.'),
('Cipermetrina', 'Insecticida piretroide de contacto contra polilla del racimo y trips. Acción rápida. Dosis: 0.3-0.5 L/ha.'),
('Bacillus thuringiensis', 'Insecticida biológico contra larvas de lepidópteros (polilla del racimo). Selectivo, no afecta fauna auxiliar. Dosis: 1-2 kg/ha.'),
('Aceite de neem', 'Insecticida/acaricida natural contra arañuela, pulgón y trips. Acción repelente y reguladora de crecimiento. Dosis: 2-3 L/ha.'),
('Abamectina', 'Acaricida sistémico contra arañuela amarilla. Acción translaminar. Respetar intervalo de reentrada. Dosis: 0.5-0.75 L/ha.'),
('Espinosad', 'Insecticida biológico derivado de Saccharopolyspora spinosa. Contra polilla del racimo y trips. Baja toxicidad para abejas. Dosis: 0.1-0.15 L/ha.'),
('Quelato de hierro (EDDHA)', 'Corrector de clorosis férrica. Aplicación al suelo o foliar. Eficaz en suelos calcáreos pH > 7.5. Dosis: 20-40 g/planta al suelo.'),
('Sulfato de magnesio', 'Corrector de carencia de magnesio. Aplicación foliar o al suelo. Mejora fotosíntesis y color foliar. Dosis foliar: 2-3%.'),
('Nitrato de potasio', 'Fertilizante foliar corrector de potasio y nitrógeno. Mejora calidad de uva y resistencia a estrés. Dosis foliar: 2-3%.');
